"use client"

import * as React from "react"
import { Check, CircleAlert, Copy, Info, Loader2, Lock, LockOpen, Play, ShieldCheck, Terminal, TriangleAlert } from "lucide-react"

import { cn } from "@/lib/utils"
import { codeHostSource, parsePipeInstall, registrableDomain, reviewPipeInstall, safeInstallSteps, type PipeIssueKind, type PipeReviewOptions } from "./curl-pipe"

export { codeHostSource, isIpHost, parsePipeInstall, registrableDomain, reviewPipeInstall, safeInstallSteps, type PipeInstall, type PipeIssue, type PipeIssueKind, type PipeReviewOptions } from "./curl-pipe"

/** Every visible string. `{host}`, `{docs}`, `{site}`, `{repo}`, `{runner}` are filled in. */
export const CURL_PIPE_MESSAGES = {
  title: "Install command",
  runsFrom: "Runs a script from",
  matchesDocs: "Same site as the {docs} docs",
  noHost: "No host found",
  http: "Plain http: anyone on the network (café Wi-Fi, a proxy) can swap the script on its way to your shell.",
  "implied-http": "No https:// in the URL, so {fetcher} fetches it over plain http, where it can be swapped on the way.",
  ip: "A raw IP address instead of a domain. There's no name to check against the product, and no certificate tying it to them.",
  shortener: "A shortened link. You can't see where the script really comes from, and the link can be repointed at any time.",
  "other-domain": "{host} isn't {docs}, where the docs live. Check that the docs really point here.",
  "code-host": "Hosted on {site} under {repo}, not on {docs}. Anyone can publish there; check it's the product's own repo.",
  sudo: "Runs as root. Everything in the script can change any file on this machine.",
  insecure: "Certificate checks are off (-k / --insecure), so a fake server would be accepted.",
  "no-checksum": "The docs give no checksum or signature, so you can't confirm the script is the one they published.",
  "no-fail": "Without -f, an error page (404, 500) is fed to {runner} as if it were the script.",
  unparsed: "This isn't a download piped into a shell, so there's nothing to check here.",
  oneLine: "One line",
  steps: "Download, inspect, run",
  stepsHint: "Saves the script first, so a dropped connection can't run half of it and the server can't send a different script to a pipe than to a file. Read it in the pager (q to quit), then run it.",
  upgraded: "Switched to https in the steps. If the download fails, the host doesn't serve https.",
  copy: "Copy",
  copyAnyway: "Copy anyway",
  confirmHint: "Tap again to copy the one-liner with these risks.",
  copied: "Copied",
  copiedStatus: "Copied to the clipboard.",
  copyFailed: "Couldn't reach the clipboard. Select the text and copy it.",
  run: "Run",
  runAnyway: "Run anyway",
  running: "Running…",
  modeLabel: "How to copy it",
}
export type CurlPipeMessages = typeof CURL_PIPE_MESSAGES
export type CurlPipeMode = "one-line" | "steps"

const fill = (template: string, values: Record<string, string | number>) => template.replace(/\{(\w+)\}/g, (match, key: string) => String(values[key] ?? match))
const tone = {
  danger: "text-red-700 dark:text-red-400",
  warning: "text-amber-800 dark:text-amber-300",
  info: "text-muted-foreground",
}
// `. <(curl …)` reads best as "source".
const runnerName = (runner?: string) => (!runner ? "sh" : runner === "." ? "source" : runner)
const icons = { danger: CircleAlert, warning: TriangleAlert, info: Info }
const button = "inline-flex h-8 items-center justify-center gap-1.5 rounded-md px-3 text-sm font-medium outline-none transition-colors focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50"

export interface CurlPipeGuardProps extends PipeReviewOptions, Omit<React.ComponentProps<"div">, "onCopy"> {
  /** The install one-liner as the docs show it, e.g. `curl -fsSL https://bun.sh/install | bash`. */
  command: string
  /** Controlled copy mode. */
  mode?: CurlPipeMode
  /** Initial mode when uncontrolled. Defaults to the safer steps whenever something is flagged. */
  defaultMode?: CurlPipeMode
  /** Called when the user switches between the one-liner and the steps. */
  onModeChange?: (mode: CurlPipeMode) => void
  /** Called after a successful copy with exactly what was copied. */
  onCopy?: (text: string, mode: CurlPipeMode) => void
  /** Shows a Run button (for terminals and IDEs). May return a Promise; the button shows a pending state and ignores repeat clicks. */
  onRun?: (text: string, mode: CurlPipeMode) => void | Promise<void>
  /** Any visible string. */
  messages?: Partial<CurlPipeMessages>
}

/**
 * Prevents running an install script from somewhere you didn't mean to trust. Before a `curl … | sh` (or wget, or
 * `iwr | iex`) is copied or run it shows the script's real host, flags plain http, raw IPs, shortened links, a host that
 * isn't the product's docs domain, sudo, -k/--insecure, a missing checksum and a missing -f, and offers the same install
 * as "download, inspect, then run" steps to copy instead. Risky one-liners need a second tap.
 */
export function CurlPipeGuard({
  command,
  docsDomain,
  checksum,
  verify,
  trustedSources,
  mode,
  defaultMode,
  onModeChange,
  onCopy,
  onRun,
  messages,
  className,
  ...props
}: CurlPipeGuardProps) {
  const t = { ...CURL_PIPE_MESSAGES, ...messages }
  const install = React.useMemo(() => parsePipeInstall(command), [command])
  const issues = React.useMemo(() => reviewPipeInstall(install, { docsDomain, checksum, verify, trustedSources }), [install, docsDomain, checksum, verify, trustedSources])
  const risky = issues.some((i) => i.severity !== "info") && !!install
  const [innerMode, setInnerMode] = React.useState<CurlPipeMode>(defaultMode ?? (risky ? "steps" : "one-line"))
  const current = install ? (mode ?? innerMode) : "one-line"
  const [armed, setArmed] = React.useState<"copy" | "run" | null>(null)
  const [copied, setCopied] = React.useState(false)
  const [pending, setPending] = React.useState(false)
  const [status, setStatus] = React.useState("")
  const busy = React.useRef(false)
  const id = React.useId()

  const steps = install ? safeInstallSteps(install, { checksum, verify }) : []
  const text = current === "steps" ? steps.join("\n") : String(command ?? "").replace(/^\uFEFF/, "").trim()
  const source = install ? codeHostSource(install.url) : null
  const docs = docsDomain ? registrableDomain(docsDomain.replace(/^https?:\/\//i, "").split("/")[0]) : ""
  const values = { host: install?.host ?? "", docs, site: source?.site ?? "", repo: source?.repo ?? "", runner: runnerName(install?.runner), fetcher: install?.fetcher ?? "curl" }
  const sameSite = !!docs && !!install?.host && registrableDomain(install.host) === docs
  const needsSecondTap = current === "one-line" && risky

  // A new command or mode is a new decision: disarm any half-confirmed copy.
  React.useEffect(() => setArmed(null), [command, current])
  React.useEffect(() => {
    if (!armed) return
    const timer = setTimeout(() => setArmed(null), 5000)
    return () => clearTimeout(timer)
  }, [armed])

  const describe = (action: "copy" | "run") => [issues.length > 0 && `${id}-issues`, armed === action && `${id}-armed`].filter(Boolean).join(" ") || undefined
  const choose = (next: CurlPipeMode) => {
    if (mode === undefined) setInnerMode(next)
    onModeChange?.(next)
  }
  const copy = async () => {
    if (needsSecondTap && armed !== "copy") return setArmed("copy")
    setArmed(null)
    try {
      await navigator.clipboard.writeText(text)
      setCopied(true)
      setStatus(t.copiedStatus)
      onCopy?.(text, current)
      setTimeout(() => setCopied(false), 1500)
    } catch {
      setStatus(t.copyFailed)
    }
  }
  const run = async () => {
    if (!onRun || busy.current) return
    if (needsSecondTap && armed !== "run") return setArmed("run")
    setArmed(null)
    busy.current = true
    setPending(true)
    try {
      await onRun(text, current)
    } catch {
      // The caller reports run failures; the button becomes usable again.
    } finally {
      busy.current = false
      setPending(false)
    }
  }

  return (
    <div data-slot="curl-pipe-guard" data-risk={risky ? "risky" : "ok"} className={cn("w-full max-w-lg min-w-0 overflow-hidden rounded-xl border bg-background text-sm", className)} {...props}>
      <div className="flex items-center gap-2 border-b px-4 py-3">
        <Terminal aria-hidden className="size-4 shrink-0 text-muted-foreground" />
        <h3 id={`${id}-title`} className="min-w-0 flex-1 font-medium">{t.title}</h3>
        {install && <span className="rounded-md border px-1.5 py-0.5 font-mono text-xs text-muted-foreground">{install.platform === "powershell" ? "PowerShell" : runnerName(install.runner)}</span>}
      </div>

      <div className="grid grid-cols-[minmax(0,1fr)] gap-3 px-4 py-3">
        {install?.host && (
          <div className="grid gap-0.5">
            <span className="text-xs text-muted-foreground">{t.runsFrom}</span>
            <span className="flex min-w-0 items-center gap-1.5">
              {install.scheme === "https" && !install.impliedHttp ? <Lock aria-hidden className="size-4 shrink-0 text-muted-foreground" /> : <LockOpen aria-hidden className="size-4 shrink-0 text-red-600 dark:text-red-400" />}
              <strong className="min-w-0 font-mono text-base font-semibold [overflow-wrap:anywhere]">{install.host}</strong>
            </span>
            <span className="font-mono text-xs text-muted-foreground [overflow-wrap:anywhere]">{install.url}</span>
            {sameSite && (
              <span className="mt-0.5 flex items-center gap-1.5 text-xs text-emerald-700 dark:text-emerald-400">
                <ShieldCheck aria-hidden className="size-3.5" />
                {fill(t.matchesDocs, values)}
              </span>
            )}
          </div>
        )}

        {issues.length > 0 && (
          <ul id={`${id}-issues`} className="grid gap-1.5">
            {issues.map((issue) => {
              const Icon = icons[issue.severity]
              return (
                <li key={issue.kind} data-kind={issue.kind} className={cn("flex gap-1.5 text-xs", tone[issue.severity])}>
                  <Icon aria-hidden className="mt-0.5 size-3.5 shrink-0" />
                  <span className="min-w-0 [overflow-wrap:anywhere]">{fill(t[issue.kind as PipeIssueKind], values)}</span>
                </li>
              )
            })}
          </ul>
        )}

        {install && (
          <div role="radiogroup" aria-label={t.modeLabel} className="grid grid-cols-2 gap-1 rounded-md bg-muted p-1">
            {(["one-line", "steps"] as const).map((m) => (
              <button
                key={m}
                type="button"
                role="radio"
                aria-checked={current === m}
                tabIndex={current === m ? 0 : -1}
                onClick={() => choose(m)}
                onKeyDown={(e) => {
                  if (!["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown"].includes(e.key)) return
                  e.preventDefault()
                  const next = m === "one-line" ? "steps" : "one-line"
                  choose(next)
                  ;(e.currentTarget.parentElement?.querySelector(`[data-mode="${next}"]`) as HTMLElement | null)?.focus()
                }}
                data-mode={m}
                className={cn("min-h-8 rounded-[5px] px-2 py-1 text-xs font-medium outline-none transition-colors focus-visible:ring-[3px] focus-visible:ring-ring/50", current === m ? "bg-background text-foreground shadow-xs" : "text-muted-foreground hover:text-foreground")}
              >
                {m === "one-line" ? t.oneLine : t.steps}
              </button>
            ))}
          </div>
        )}

        <pre className="overflow-x-auto rounded-md bg-muted px-3 py-2 font-mono text-xs leading-5 whitespace-pre-wrap [overflow-wrap:anywhere]">
          {current === "steps" ? steps.map((line, i) => <div key={i}>{line}</div>) : text}
        </pre>
        {current === "steps" && (
          <p className="-mt-1.5 text-xs text-muted-foreground">
            {t.stepsHint}
            {install && (install.scheme === "http" || install.impliedHttp) && ` ${t.upgraded}`}
          </p>
        )}
        {armed && <p id={`${id}-armed`} className="-mt-1.5 flex gap-1.5 text-xs font-medium text-red-700 dark:text-red-400"><TriangleAlert aria-hidden className="mt-0.5 size-3.5 shrink-0" />{t.confirmHint}</p>}
      </div>

      <span role="status" className="sr-only">{status}</span>
      <div className="flex flex-wrap justify-end gap-2 border-t px-4 py-3">
        {onRun && install && (
          <button type="button" onClick={run} disabled={pending} aria-busy={pending || undefined} aria-describedby={describe("run")} className={cn(button, "border bg-background hover:bg-accent", armed === "run" && "border-red-500/50 text-red-700 dark:text-red-400")}>
            {pending ? <Loader2 aria-hidden className="size-4 animate-spin" /> : <Play aria-hidden className="size-4" />}
            {pending ? t.running : armed === "run" ? t.runAnyway : t.run}
          </button>
        )}
        <button type="button" onClick={copy} aria-describedby={describe("copy")} className={cn(button, armed === "copy" ? "bg-destructive text-white hover:bg-destructive/90" : "bg-primary text-primary-foreground hover:bg-primary/90")}>
          {copied ? <Check aria-hidden className="size-4" /> : <Copy aria-hidden className="size-4" />}
          {copied ? t.copied : armed === "copy" ? t.copyAnyway : t.copy}
        </button>
      </div>
    </div>
  )
}

// Pure parsing and review for "curl … | sh"-style install one-liners. Safe on the server.

export type PipeIssueKind = "http" | "implied-http" | "ip" | "shortener" | "other-domain" | "code-host" | "sudo" | "insecure" | "no-checksum" | "no-fail" | "unparsed"

export interface PipeIssue {
  kind: PipeIssueKind
  severity: "danger" | "warning" | "info"
}

export interface PipeInstall {
  /** "unix" for curl/wget into a shell, "powershell" for iwr/irm into iex. */
  platform: "unix" | "powershell"
  fetcher: string
  url: string
  /** Lowercased host, without port. Empty when no URL was found. */
  host: string
  scheme: "https" | "http"
  /** The URL had no scheme, so curl/wget fall back to plain http. */
  impliedHttp: boolean
  /** The program the script is fed to: sh, bash, zsh, python3, source, ".", iex… */
  runner: string
  /** Arguments passed to the script itself, e.g. ["--yes"] from `sh -s -- --yes`, as written (quotes kept). */
  args: string[]
  /** The runner's own options, e.g. ["-x"] from `bash -x`. */
  runnerOptions: string[]
  /** What runs the runner, as written: `sudo -E`, `env FOO=1`, `ENV="$HOME/.bashrc"`. Empty when nothing does. */
  prefix: string
  /** Commands chained after the install with `&&` or `;`, e.g. `sudo apt-get install -y nodejs`. */
  then: string
  /** The script itself runs as root (`| sudo bash`, `sudo sh -c "$(curl …)"`). */
  sudo: boolean
  insecure: boolean
  /** curl was given -f/--fail, so an HTTP error page isn't piped into the shell. */
  fail: boolean
}

export interface PipeReviewOptions {
  /** The product's docs domain, e.g. "bun.sh". The script host should be it or a subdomain of it. */
  docsDomain?: string
  /** SHA-256 the docs publish for the script (64 hex characters). */
  checksum?: string
  /** A signature check the docs give, e.g. `gpg --verify install.sh.asc install.sh`. */
  verify?: string
  /** Hosts or host/path prefixes you trust, e.g. "raw.githubusercontent.com/Homebrew". */
  trustedSources?: string[]
}

const SHORTENERS = new Set(["bit.ly", "tinyurl.com", "t.co", "goo.gl", "is.gd", "ow.ly", "buff.ly", "rebrand.ly", "cutt.ly", "shorturl.at", "rb.gy", "tiny.cc", "git.io", "s.id", "v.gd", "t.ly", "lnkd.in", "bl.ink", "short.io"])
// Two-label public suffixes, so "example.co.uk" (not "co.uk") is the registrable domain.
const TWO_LABEL = new Set(["co.uk", "org.uk", "ac.uk", "gov.uk", "com.au", "net.au", "org.au", "co.in", "net.in", "org.in", "co.jp", "com.br", "com.cn", "co.nz", "co.za", "com.mx", "com.sg", "com.tr", "github.io", "gitlab.io", "vercel.app", "netlify.app", "pages.dev", "workers.dev", "herokuapp.com", "web.app", "firebaseapp.com"])
const CODE_HOSTS: Record<string, string> = { "raw.githubusercontent.com": "GitHub", "github.com": "GitHub", "gist.githubusercontent.com": "GitHub Gist", "objects.githubusercontent.com": "GitHub", "gitlab.com": "GitLab", "bitbucket.org": "Bitbucket", "codeberg.org": "Codeberg" }
const RUNNERS = "sh|bash|zsh|dash|ksh|fish|python3?|node|perl|ruby|iex|invoke-expression"

export const isIpHost = (host: string) => /^\d{1,3}(\.\d{1,3}){3}$/.test(host) || host.startsWith("[") || /^[0-9a-f:]+$/i.test(host) && host.includes(":")

/** "get.example.co.uk" → "example.co.uk". IPs come back unchanged. */
export function registrableDomain(host: string) {
  const h = host.toLowerCase().replace(/\.$/, "")
  if (isIpHost(h)) return h
  const labels = h.split(".")
  const take = TWO_LABEL.has(labels.slice(-2).join(".")) ? 3 : 2
  return labels.slice(-take).join(".")
}

/** Owner/repo for scripts on a code host, where anyone can publish under any name. */
export function codeHostSource(url: string) {
  try {
    const u = new URL(url)
    const site = CODE_HOSTS[u.hostname.toLowerCase()]
    if (!site) return null
    const [owner = "", repo = ""] = u.pathname.split("/").filter(Boolean)
    return { site, repo: [owner, repo].filter(Boolean).join("/") }
  } catch {
    return null
  }
}

type Segment = { text: string; op: string }

/** Splits on top-level `|`, `||`, `&&`, `;`, `&`, leaving quotes and `$( )`/`<( )` groups whole. */
function splitTop(cmd: string) {
  const out: Segment[] = []
  let quote = ""
  let depth = 0
  let cur = ""
  for (let i = 0; i < cmd.length; i++) {
    const ch = cmd[i]
    if (quote) {
      if (ch === quote) quote = ""
      else if (ch === "\\" && quote === '"') cur += ch + (cmd[++i] ?? "")
      else if (quote === '"' && ch === "$" && cmd[i + 1] === "(") depth++
      if (ch !== "\\") cur += ch
      continue
    }
    if (ch === "'" || ch === '"') quote = ch
    else if (ch === "(") depth++
    else if (ch === ")") depth = Math.max(0, depth - 1)
    else if (!depth && /[|;&]/.test(ch)) {
      const op = /[|&]/.test(cmd[i + 1] ?? "") && cmd[i + 1] === ch ? ch + cmd[++i] : ch
      out.push({ text: cur.trim(), op })
      cur = ""
      continue
    }
    cur += ch
  }
  out.push({ text: cur.trim(), op: "" })
  return out
}

/** Shell words with quotes and `$( )`/`<( )` groups kept as written. */
function words(text: string) {
  const out: string[] = []
  let quote = ""
  let depth = 0
  let cur = ""
  for (const ch of text) {
    if (quote) {
      if (ch === quote) quote = ""
    } else if (ch === "'" || ch === '"') quote = ch
    else if (ch === "(") depth++
    else if (ch === ")") depth = Math.max(0, depth - 1)
    else if (!depth && ch === " ") {
      if (cur) out.push(cur)
      cur = ""
      continue
    }
    cur += ch
  }
  if (cur) out.push(cur)
  return out
}

const RUNNER_RE = new RegExp(`^(?:[\\w./-]*/)?(${RUNNERS}|source|\\.)$`, "i")
// sudo options that take a value: `sudo -u deploy bash`.
const SUDO_ARG = /^-[ughpCDrtUT]$/

/** `sudo -E env FOO=1 bash -x -s -- --yes` → prefix, runner, its own options and the script's arguments. */
function readRunner(list: string[]) {
  let i = 0
  const prefix: string[] = []
  let sudo = false
  if (list[i] === "sudo") {
    sudo = true
    prefix.push(list[i++])
    while (i < list.length && list[i].startsWith("-")) {
      prefix.push(list[i])
      if (SUDO_ARG.test(list[i++]) && i < list.length) prefix.push(list[i++])
    }
  }
  if (list[i] === "env") {
    prefix.push(list[i++])
    while (i < list.length && list[i].startsWith("-")) prefix.push(list[i++])
  }
  while (i < list.length && /^[A-Za-z_]\w*=/.test(list[i])) prefix.push(list[i++])
  const m = list[i]?.match(RUNNER_RE)
  if (!m) return null
  const runner = m[1].toLowerCase()
  const options: string[] = []
  let j = i + 1
  let stdin = false
  for (; j < list.length; j++) {
    const w = list[j]
    if (w === "--" || w === "-" || w === "/dev/stdin") {
      stdin = true
      j++
      if (w !== "--" && list[j] === "--") j++
      break
    }
    if (w === "-s") {
      stdin = true
      j++
      if (list[j] === "--") j++
      break
    }
    if (!w.startsWith("-")) break
    options.push(w)
  }
  return { runner, prefix: prefix.join(" "), sudo, options, rest: list.slice(j), stdin }
}

/** Reads a curl/wget/iwr/irm one-liner. Returns null when it isn't a download fed to an interpreter. */
export function parsePipeInstall(input: unknown): PipeInstall | null {
  if (typeof input !== "string") return null
  let cmd = input.replace(/^\uFEFF/, "").replace(/\\\r?\n/g, " ").replace(/\r?\n/g, " ").replace(/\s+/g, " ").trim().slice(0, 4000)
  cmd = cmd.replace(/^\$\s+/, "").replace(/^PS [^>]*>\s*/, "")
  // powershell -c "irm … | iex" — look inside the quoted command.
  const wrapped = cmd.match(/^(?:powershell|pwsh)(?:\.exe)?(?:\s+-\w+(?:\s+(?!-c)\w+)?)*?\s+-c(?:ommand)?\s+(["'])(.*)\1/i)
  if (wrapped) cmd = wrapped[2]
  const FETCH = /\b(curl|wget|iwr|irm|invoke-webrequest|invoke-restmethod)\b(?:\.exe)?/i
  const fetch = cmd.match(FETCH)
  if (!fetch) return null
  const fetcher = fetch[1].toLowerCase()
  const powershell = /^(iwr|irm|invoke-)/.test(fetcher) || /\b(iex|invoke-expression)\b/i.test(cmd)

  let runner = ""
  let prefix = ""
  let sudo = false
  let options: string[] = []
  let args: string[] = []
  let then = ""
  let fetchPart = ""

  if (powershell) {
    // `irm … | iex`, `iex (irm …)`, `iex "& { $(irm …) } -Arg"`.
    const after = cmd.slice(fetch.index! + fetch[0].length)
    const piped = after.match(/\|\s*(iex|invoke-expression)\b/i)
    const before = cmd.slice(0, fetch.index)
    if (!piped && !/\b(iex|invoke-expression)\b/i.test(before)) return null
    runner = "iex"
    fetchPart = piped ? after.slice(0, piped.index) : after.split(")")[0]
    const scriptArgs = !piped && after.match(/\)\s*\}\s*([^"']*)["']/)
    if (scriptArgs) args = scriptArgs[1].trim().split(" ").filter(Boolean)
  } else {
    const segments = splitTop(cmd)
    const k = segments.findIndex((s) => FETCH.test(s.text))
    let last = k
    const seg = segments[k].text
    const inner = seg.match(/(?:\$\(|<\()([^)]*)\)/)
    if (inner && FETCH.test(inner[1])) {
      // `bash -c "$(curl …)" "" --flag`, `bash <(curl …) --flag`, `source <(curl …)`.
      const list = words(seg)
      const at = list.findIndex((w) => FETCH.test(w))
      const r = readRunner(list.slice(0, at).concat("--"))
      if (!r) return null
      ;({ runner, prefix, sudo } = r)
      options = r.options.filter((o) => o !== "-c")
      args = list.slice(at + 1)
      if (r.options.includes("-c")) args = args.slice(1) // the first word after -c "…" is $0
      fetchPart = inner[1].slice((inner[1].match(FETCH)?.index ?? 0) + fetch[0].length)
    } else {
      fetchPart = seg.slice((seg.match(FETCH)?.index ?? 0) + fetch[0].length)
      // Skip pass-through stages such as `| tee install.sh |`.
      for (let i = k; i < segments.length - 1 && segments[i].op === "|"; i++) {
        const r = readRunner(words(segments[i + 1].text))
        if (r) {
          ;({ runner, prefix, sudo, options } = r)
          args = r.rest
          last = i + 1
          break
        }
        if (!/^(tee|cat|dd)\b/.test(segments[i + 1].text)) return null
      }
      if (!runner) return null
    }
    // `… | bash - && sudo apt-get install -y nodejs`: keep what runs afterwards as its own step.
    then = segments.slice(last + 1).map((s) => s.text + (s.op && s.op !== ";" ? " " + s.op : "")).join(" ").trim().replace(/\s*(&&|\|\||;)$/, "")
    if (segments[last].op === "|" || segments[last].op === "&") then = ""
  }

  const explicit = fetchPart.match(/\bhttps?:\/\/[^\s'"|;)<>`]+/i)
  const bare = explicit ? null : fetchPart.split(" ").find((tok) => !tok.startsWith("-") && /^[\w-]+(\.[\w-]+)+(:\d+)?(\/\S*)?$/.test(tok.replace(/^['"]|['"]$/g, "")))
  const url = explicit ? explicit[0] : bare ? `http://${bare.replace(/^['"]|['"]$/g, "")}` : ""
  let host = ""
  let scheme: "https" | "http" = "https"
  try {
    const u = new URL(url)
    host = u.hostname.toLowerCase()
    scheme = u.protocol === "http:" ? "http" : "https"
  } catch {
    // No usable URL; the review reports it as unparsed.
  }
  const flags = fetchPart.split(" ").filter((tok) => tok.startsWith("-"))
  const shortHas = (letter: string) => flags.some((f) => /^-[a-zA-Z]+$/.test(f) && f.includes(letter))
  const curl = fetcher === "curl"
  return {
    platform: powershell ? "powershell" : "unix",
    fetcher,
    url,
    host,
    scheme,
    impliedHttp: !!bare,
    runner: runner === "invoke-expression" ? "iex" : runner,
    args,
    runnerOptions: options,
    prefix,
    then,
    sudo,
    insecure: (curl && (shortHas("k") || flags.includes("--insecure"))) || flags.includes("--no-check-certificate") || /-SkipCertificateCheck\b/i.test(fetchPart),
    fail: !curl || shortHas("f") || flags.some((f) => f === "--fail" || f === "--fail-with-body"),
  }
}

const isChecksum = (value?: string) => typeof value === "string" && /^[a-f0-9]{64}$/i.test(value.trim())

/** Everything worth flagging before the one-liner is copied or run, most serious first. */
export function reviewPipeInstall(install: PipeInstall | null, options: PipeReviewOptions = {}): PipeIssue[] {
  if (!install || !install.host) return [{ kind: "unparsed", severity: "warning" }]
  const issues: PipeIssue[] = []
  const add = (kind: PipeIssueKind, severity: PipeIssue["severity"]) => issues.push({ kind, severity })
  const trusted = (options.trustedSources ?? []).some((src) => {
    const bare = install.url.replace(/^https?:\/\//i, "").toLowerCase()
    const s = src.toLowerCase().replace(/^https?:\/\//, "").replace(/\/$/, "")
    return bare === s || bare.startsWith(s + "/") || install.host === s
  })
  if (install.impliedHttp) add("implied-http", "danger")
  else if (install.scheme === "http") add("http", "danger")
  if (isIpHost(install.host)) add("ip", "danger")
  else if (SHORTENERS.has(install.host)) add("shortener", "danger")
  else if (options.docsDomain && !trusted) {
    const docs = registrableDomain(options.docsDomain.replace(/^https?:\/\//i, "").split("/")[0])
    if (registrableDomain(install.host) !== docs) add(codeHostSource(install.url) ? "code-host" : "other-domain", "warning")
  }
  if (install.insecure) add("insecure", "danger")
  if (install.sudo) add("sudo", "warning")
  if (!isChecksum(options.checksum) && !options.verify?.trim()) add("no-checksum", "warning")
  if (!install.fail) add("no-fail", "info")
  return issues
}

/** The same install as separate steps: download to a file, read it, verify it, then run it. */
export function safeInstallSteps(install: PipeInstall, options: Pick<PipeReviewOptions, "checksum" | "verify"> = {}) {
  const url = install.url.replace(/^http:/i, "https:")
  const base = (() => {
    try {
      return new URL(url).pathname.split("/").pop() ?? ""
    } catch {
      return ""
    }
  })()
  const sum = isChecksum(options.checksum) ? options.checksum!.trim() : ""
  const args = install.args.length ? " " + install.args.join(" ") : ""
  if (install.platform === "powershell") {
    const file = /^[\w.-]+\.ps1$/i.test(base) ? base : "install.ps1"
    return [
      `Invoke-WebRequest -Uri "${url}" -OutFile ${file} -UseBasicParsing`,
      `notepad ${file}`,
      ...(sum ? [`if ((Get-FileHash ${file} -Algorithm SHA256).Hash -ne "${sum.toUpperCase()}") { throw "Checksum mismatch" }`] : []),
      ...(options.verify?.trim() ? [options.verify.trim()] : []),
      `powershell -ExecutionPolicy Bypass -File .\\${file}${args}`,
    ]
  }
  const ext = install.runner.startsWith("python") ? ".py" : install.runner === "node" ? ".js" : install.runner === "perl" ? ".pl" : install.runner === "ruby" ? ".rb" : ".sh"
  const file = /^[\w.-]+\.(sh|bash|py|js|pl|rb)$/i.test(base) ? base : `install${ext}`
  const download = install.fetcher === "wget" ? `wget -O ${file} "${url}"` : `curl -fsSL --proto '=https' --tlsv1.2 -o ${file} "${url}"`
  const runner = install.runner === "iex" ? "sh" : install.runner
  // `.`/`source` look a bare name up in PATH first, so point at the file.
  const target = runner === "." || runner === "source" ? `./${file}` : file
  const prefix = install.prefix ?? (install.sudo ? "sudo" : "")
  const opts = install.runnerOptions?.length ? " " + install.runnerOptions.join(" ") : ""
  return [
    download,
    `less ${file}`,
    ...(sum ? [`echo "${sum.toLowerCase()}  ${file}" | shasum -a 256 -c`] : []),
    ...(options.verify?.trim() ? [options.verify.trim()] : []),
    `${prefix ? prefix + " " : ""}${runner}${opts} ${target}${args}`,
    ...(install.then ? [install.then] : []),
  ]
}
